def save(self, name, content, max_length=None):
    """
    Save new content to the file specified by name. The content should be
    a proper File object or any Python file-like object, ready to be read
    from the beginning.
    """
    # Get the proper name for the file, as it will actually be saved.
    if name is None:
        name = content.name

    if not hasattr(content, 'chunks'):
        content = File(content, name)

    name = self.get_available_name(name, max_length=max_length)
    return self._save(name, content)

def generate_filename(self, filename):
    """
    Validate the filename by calling get_valid_name() and return a filename
    to be passed to the save() method.
    """
    # `filename` may include a path as returned by FileField.upload_to.
    dirname, filename = os.path.split(filename)
    if '..' in pathlib.PurePath(dirname).parts:
        raise SuspiciousFileOperation("Detected path traversal attempt in '%s'" % dirname)
    return os.path.normpath(os.path.join(dirname, self.get_valid_name(filename)))

def traverse(cls, base, request, path_items):
    """See ``zope.app.pagetemplate.engine``."""

    path_items = list(path_items)
    path_items.reverse()

    while path_items:
        name = path_items.pop()

        if name == '_':
            warnings.warn('Traversing to the name `_` is deprecated '
                          'and will be removed in Zope 6.',
                          DeprecationWarning)
        elif name.startswith('_'):
            raise NotFound(name)

        if ITraversable.providedBy(base):
            base = getattr(base, cls.traverse_method)(name)
        else:
            base = traversePathElement(base, name, path_items,
                                       request=request)

    return base

